bool Wheel(UnityEngine.UI.ScrollRect scroll){var p=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=Bounds(scroll.viewport).center,scrollDelta=new Vector2(0,-3)};var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(p,hits);bool hit=hits.Count>0&&hits[0].gameObject.GetComponentInParent<UnityEngine.UI.ScrollRect>()==scroll;if(hit)UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,UnityEngine.EventSystems.ExecuteEvents.scrollHandler);return hit;}
bool DragBar(UnityEngine.UI.ScrollRect scroll){var bar=scroll.verticalScrollbar;var p=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=Bounds(bar.handleRect).center,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};p.pressPosition=p.position;var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(p,hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Scrollbar>()!=bar)return false;var target=hits[0].gameObject;UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(target,p,UnityEngine.EventSystems.ExecuteEvents.pointerDownHandler);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(target,p,UnityEngine.EventSystems.ExecuteEvents.initializePotentialDrag);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(target,p,UnityEngine.EventSystems.ExecuteEvents.beginDragHandler);var bounds=Bounds((RectTransform)bar.transform);p.position=new Vector2(bounds.center.x,bounds.yMin+1);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(target,p,UnityEngine.EventSystems.ExecuteEvents.dragHandler);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(target,p,UnityEngine.EventSystems.ExecuteEvents.endDragHandler);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(target,p,UnityEngine.EventSystems.ExecuteEvents.pointerUpHandler);return true;}
bool FinalGlyphVisible(UnityEngine.UI.Text label,RectTransform viewport){label.cachedTextGenerator.Populate(label.text,label.GetGenerationSettings(label.rectTransform.rect.size));var verts=label.cachedTextGenerator.verts;for(int i=verts.Count-4;i>=0;i-=4){float minX=float.MaxValue,minY=float.MaxValue,maxX=float.MinValue,maxY=float.MinValue;for(int n=0;n<4;n++){var p=verts[i+n].position;minX=Mathf.Min(minX,p.x);maxX=Mathf.Max(maxX,p.x);minY=Mathf.Min(minY,p.y);maxY=Mathf.Max(maxY,p.y);}if(maxX-minX>.01f&&maxY-minY>.01f){var point=label.transform.TransformPoint(new Vector3((minX+maxX)*.5f,(minY+maxY)*.5f,0)/label.pixelsPerUnit);return Bounds(viewport).Contains(point);}}return false;}
